// ---------------------------------------------------------------------------
// GEMM: C[M,N] (op)= A[M,K] · W[N,K]ᵀ, the PyTorch Linear layout, with an
// epilogue for bias, activation, residual add, GeGLU and RoPE.
// ---------------------------------------------------------------------------

struct GemmParams {
    uint M, N, K;
    uint lda, ldc;
    uint flags;
    uint aux; // kRope: columns below this get RoPE (2·hidden: q and k)
};

constant constexpr uint kBias = 1;     // add bias[n]
constant constexpr uint kResidual = 2; // C += result (after bias and activation)
constant constexpr uint kReLU = 4;
constant constexpr uint kGELU = 8;

// erf: the rational minimax approximation Eigen and XLA use (the same one as
// the CPU engine's Erf32), clamped to [-4, 4].
inline float erf_approx(float x) {
    x = clamp(x, -4.0f, 4.0f);
    float x2 = x * x;
    float p = fma(x2, -2.72614225801306e-10f, 2.77068142495902e-08f);
    p = fma(x2, p, -2.10102402082508e-06f);
    p = fma(x2, p, -5.69250639462346e-05f);
    p = fma(x2, p, -7.34990630326855e-04f);
    p = fma(x2, p, -2.95459980854025e-03f);
    p = fma(x2, p, -1.60960333262415e-02f);
    p = x * p;
    float q = fma(x2, -1.45660718464996e-05f, -2.13374055278905e-04f);
    q = fma(x2, q, -1.68282697438203e-03f);
    q = fma(x2, q, -7.37332916720468e-03f);
    q = fma(x2, q, -1.42647390514189e-02f);
    return p / q;
}

inline float gelu(float x) {
    return 0.5f * x * (1.0f + erf_approx(x * 0.7071067811865476f));
}

// ---------------------------------------------------------------------------
// The GEMM kernel uses no threadgroup memory: each simdgroup
// loads its 8×8 fragments straight from device memory (Apple9-family GPUs
// cache these loads well) and owns an (8·SM)×(8·SN) block of C; a
// threadgroup is 2×2 simdgroups. A must have readable rows up to the
// threadgroup tile's end (the host pads activation buffers); rows past M are
// computed but never stored. N must be a multiple of 16·SN, K of 16.
// ---------------------------------------------------------------------------

constant constexpr uint kSwap = 16;  // grid x runs over N tiles, y over M tiles
constant constexpr uint kGeGLU = 32; // C[m, j] = GELU(in)·gate, W rows interleaved in blocks of 8
constant constexpr uint kRope = 64;  // RoPE on q and k, W rows permuted within each head

template <typename TW, uint SM, uint SN, uint GM, uint GN, bool PF>
kernel void gemmd(device const float* A [[buffer(0)]],
                  device const TW* W [[buffer(1)]],
                  device float* C [[buffer(2)]],
                  device const float* bias [[buffer(3)]],
                  constant GemmParams& p [[buffer(4)]],
                  device const int* pos [[buffer(5)]],
                  device const float* rcos [[buffer(6)]],
                  device const float* rsin [[buffer(7)]],
                  uint2 tgi [[threadgroup_position_in_grid]],
                  uint sg [[simdgroup_index_in_threadgroup]],
                  uint lane [[thread_index_in_simdgroup]]) {
    uint2 tg = (p.flags & kSwap) ? tgi.yx : tgi;
    uint sm = sg / GN, sn = sg % GN;
    uint mb = tg.x * (8 * SM * GM) + sm * 8 * SM;
    uint nb = tg.y * (8 * SN * GN) + sn * 8 * SN;
    if (mb >= p.M) return;

    simdgroup_float8x8 acc[SM][SN];
    for (uint i = 0; i < SM; i++)
        for (uint j = 0; j < SN; j++)
            acc[i][j] = make_filled_simdgroup_matrix<float, 8, 8>(0.0f);

    device const float* Ab = A + (ulong)mb * p.lda;
    device const TW* Wb = W + (ulong)nb * p.K;
    if (PF) {
        simdgroup_float8x8 a[SM], a2[SM];
        simdgroup_matrix<TW, 8, 8> b[SN], b2[SN];
        for (uint i = 0; i < SM; i++) simdgroup_load(a[i], Ab + (ulong)i * 8 * p.lda, p.lda);
        for (uint j = 0; j < SN; j++) simdgroup_load(b[j], Wb + (ulong)j * 8 * p.K, p.K, ulong2(0, 0), true);
        for (uint k = 0; k < p.K; k += 16) {
            for (uint i = 0; i < SM; i++) simdgroup_load(a2[i], Ab + (ulong)i * 8 * p.lda + k + 8, p.lda);
            for (uint j = 0; j < SN; j++) simdgroup_load(b2[j], Wb + (ulong)j * 8 * p.K + k + 8, p.K, ulong2(0, 0), true);
            for (uint i = 0; i < SM; i++)
                for (uint j = 0; j < SN; j++)
                    simdgroup_multiply_accumulate(acc[i][j], a[i], b[j], acc[i][j]);
            if (k + 16 < p.K) {
                for (uint i = 0; i < SM; i++) simdgroup_load(a[i], Ab + (ulong)i * 8 * p.lda + k + 16, p.lda);
                for (uint j = 0; j < SN; j++) simdgroup_load(b[j], Wb + (ulong)j * 8 * p.K + k + 16, p.K, ulong2(0, 0), true);
            }
            for (uint i = 0; i < SM; i++)
                for (uint j = 0; j < SN; j++)
                    simdgroup_multiply_accumulate(acc[i][j], a2[i], b2[j], acc[i][j]);
        }
    } else {
        for (uint k = 0; k < p.K; k += 8) {
            simdgroup_float8x8 a[SM];
            simdgroup_matrix<TW, 8, 8> b[SN];
            for (uint i = 0; i < SM; i++)
                simdgroup_load(a[i], Ab + (ulong)i * 8 * p.lda + k, p.lda);
            for (uint j = 0; j < SN; j++)
                simdgroup_load(b[j], Wb + (ulong)j * 8 * p.K + k, p.K, ulong2(0, 0), true);
            for (uint i = 0; i < SM; i++)
                for (uint j = 0; j < SN; j++)
                    simdgroup_multiply_accumulate(acc[i][j], a[i], b[j], acc[i][j]);
        }
    }

    // Each thread holds elements (fm, fn) and (fm, fn + 1) of every 8×8
    // fragment (the layout MLX relies on).
    uint q = lane / 4;
    uint fm = (q & 4) + ((lane / 2) % 4);
    uint fn = (q & 2) * 2 + (lane % 2) * 2;
    if (p.flags & (kGeGLU | kRope)) {
        // Fragments j and j + 1 hold paired columns: for GeGLU the input and
        // gate of the same 8 intermediate columns; for RoPE dims d and d + 32
        // of one head (the host permuted W's rows so).
        for (uint i = 0; i < SM; i++) {
            uint m = mb + i * 8 + fm;
            if (m >= p.M) continue;
            for (uint j = 0; j + 1 < SN; j += 2) {
                uint n = nb + j * 8 + fn;
                thread auto& v0 = acc[i][j].thread_elements();
                thread auto& v1 = acc[i][j + 1].thread_elements();
                float2 x1 = float2(v0[0], v0[1]), x2 = float2(v1[0], v1[1]);
                if (p.flags & kGeGLU) {
                    uint col = (n / 16) * 8 + (n % 8);
                    *(device float2*)(C + (ulong)m * p.ldc + col) = float2(gelu(x1.x) * x2.x, gelu(x1.y) * x2.y);
                    continue;
                }
                if (n < p.aux) {
                    uint dim = ((n % 64) / 16) * 8 + (n % 8);
                    uint ps = uint(pos[m]) * 64 + dim;
                    float2 c1 = float2(rcos[ps], rcos[ps + 1]), s1 = float2(rsin[ps], rsin[ps + 1]);
                    float2 c2 = float2(rcos[ps + 32], rcos[ps + 33]), s2 = float2(rsin[ps + 32], rsin[ps + 33]);
                    float2 y1 = x1 * c1 - x2 * s1;
                    float2 y2 = x2 * c2 + x1 * s2;
                    x1 = y1;
                    x2 = y2;
                }
                *(device float2*)(C + (ulong)m * p.ldc + n) = x1;
                *(device float2*)(C + (ulong)m * p.ldc + n + 8) = x2;
            }
        }
        return;
    }
    for (uint i = 0; i < SM; i++) {
        uint m = mb + i * 8 + fm;
        if (m >= p.M) continue;
        for (uint j = 0; j < SN; j++) {
            uint n = nb + j * 8 + fn;
            thread auto& v = acc[i][j].thread_elements();
            float2 r = float2(v[0], v[1]);
            if (p.flags & kBias) r += float2(bias[n], bias[n + 1]);
            if (p.flags & kReLU) r = select(r, float2(0), r < 0.0f);
            if (p.flags & kGELU) r = float2(gelu(r.x), gelu(r.y));
            device float2* c = (device float2*)(C + (ulong)m * p.ldc + n);
            if (p.flags & kResidual) *c = *c + r;
            else *c = r;
        }
    }
}

