// embed: x[t] = table[tokens[t]] as float. Grid (d/4, T).
template <typename TE>
kernel void embed(device const TE* table [[buffer(0)]],
                  device const int* tokens [[buffer(1)]],
                  device float* x [[buffer(2)]],
                  constant uint& d [[buffer(3)]],
                  uint2 gid [[thread_position_in_grid]]) {
    uint t = gid.y, j = gid.x * 4;
    ulong src = (ulong)tokens[t] * d + j;
    for (uint i = 0; i < 4; i++) x[(ulong)t * d + j + i] = float(table[src + i]);
}
template [[host_name("embed_h")]] kernel void embed<half>(device const half*, device const int*, device float*, constant uint&, uint2);
template [[host_name("embed_f")]] kernel void embed<float>(device const float*, device const int*, device float*, constant uint&, uint2);

struct NormParams {
    uint d;
    float eps;
    uint flags; // 1 bias, 2 gather rows through idx, 4 add te[qt[row]]
};

// layernorm: out[r] = (in[src] − mean) / sqrt(var + eps) · w (+ b) (+ te[qt[r]]),
// src = idx[r] when gathering, else r. One threadgroup of 256 per row; out may
// be in (each thread writes only what it read).
kernel void layernorm(device const float* in [[buffer(0)]],
                      device float* out [[buffer(1)]],
                      device const float* w [[buffer(2)]],
                      device const float* b [[buffer(3)]],
                      device const int* idx [[buffer(4)]],
                      device const float* te [[buffer(5)]],
                      device const int* qt [[buffer(6)]],
                      constant NormParams& p [[buffer(7)]],
                      uint row [[threadgroup_position_in_grid]],
                      uint tid [[thread_index_in_threadgroup]],
                      uint sg [[simdgroup_index_in_threadgroup]],
                      uint lane [[thread_index_in_simdgroup]]) {
    threadgroup float red[8];
    uint src = (p.flags & 2) ? uint(idx[row]) : row;
    device const float* x = in + (ulong)src * p.d;
    float v[8];
    uint cnt = 0;
    float s = 0;
    for (uint j = tid; j < p.d; j += 256) { v[cnt] = x[j]; s += v[cnt]; cnt++; }
    s = simd_sum(s);
    if (lane == 0) red[sg] = s;
    threadgroup_barrier(mem_flags::mem_threadgroup);
    s = 0;
    for (uint i = 0; i < 8; i++) s += red[i];
    float mean = s / float(p.d);
    threadgroup_barrier(mem_flags::mem_threadgroup);
    float ss = 0;
    for (uint i = 0; i < cnt; i++) { float dv = v[i] - mean; ss += dv * dv; }
    ss = simd_sum(ss);
    if (lane == 0) red[sg] = ss;
    threadgroup_barrier(mem_flags::mem_threadgroup);
    ss = 0;
    for (uint i = 0; i < 8; i++) ss += red[i];
    float rstd = 1.0f / sqrt(ss / float(p.d) + p.eps);
    device float* o = out + (ulong)row * p.d;
    device const float* t = (p.flags & 4) ? te + (ulong)qt[row] * p.d : te;
    cnt = 0;
    for (uint j = tid; j < p.d; j += 256) {
        float y = ((v[cnt] - mean) * rstd) * w[j];
        if (p.flags & 1) y += b[j];
        if (p.flags & 4) y += t[j];
        o[j] = y;
        cnt++;
    }
}

struct DotParams {
    uint N, K, lda;
};

// rowdot: out[r, n] = A[r] · W[n] + b[n] for tiny N (float weights).
// One simdgroup per (n, r): grid of threadgroups (N, rows), 32 threads each.
kernel void rowdot(device const float* A [[buffer(0)]],
                   device const float* W [[buffer(1)]],
                   device const float* b [[buffer(2)]],
                   device float* out [[buffer(3)]],
                   constant DotParams& p [[buffer(4)]],
                   uint2 tg [[threadgroup_position_in_grid]],
                   uint lane [[thread_index_in_simdgroup]]) {
    uint n = tg.x, r = tg.y;
    device const float* a = A + (ulong)r * p.lda;
    device const float* w = W + (ulong)n * p.K;
    float s = 0;
    for (uint k = lane; k < p.K; k += 32) s += a[k] * w[k];
    s = simd_sum(s);
    if (lane == 0) out[r * p.N + n] = s + b[n];
}

struct ActParams {
    uint d, ld;   // hidden width, act input row stride (≥ d + 4)
    uint clsRow;  // 1: sequence i's CLS row is row i of x; 0: its first token row
};

// act_prep: row i of the act head's input is [x[CLS of i], top1, top1 − top2,
// entropy / log k, k / 255, 0…], with probabilities from an untempered softmax
// of sequence i's logits. seq[i] = {first token row, first logit, logit count}.
kernel void act_prep(device const float* x [[buffer(0)]],
                     device const float* logits [[buffer(1)]],
                     device const int4* seq [[buffer(2)]],
                     device float* out [[buffer(3)]],
                     constant ActParams& p [[buffer(4)]],
                     uint i [[threadgroup_position_in_grid]],
                     uint tid [[thread_index_in_threadgroup]]) {
    int4 s = seq[i];
    device float* o = out + (ulong)i * p.ld;
    device const float* cls = x + (ulong)(p.clsRow ? int(i) : s.x) * p.d;
    for (uint j = tid; j < p.d; j += 256) o[j] = cls[j];
    for (uint j = p.d + 4 + tid; j < p.ld; j += 256) o[j] = 0;
    if (tid != 0) return;
    device const float* l = logits + s.y;
    int k = s.z;
    float mx = l[0];
    for (int j = 1; j < k; j++) mx = max(mx, l[j]);
    float sum = 0;
    for (int j = 0; j < k; j++) sum += exp(l[j] - mx);
    float top1 = 0, top2 = 0, ent = 0;
    for (int j = 0; j < k; j++) {
        float pf = exp(l[j] - mx) / sum;
        if (pf > top1) { top2 = top1; top1 = pf; }
        else if (pf > top2) { top2 = pf; }
        ent -= pf * log(max(pf, 1e-9f));
    }
    float kk = float(max(k, 2));
    o[p.d] = top1;
    o[p.d + 1] = top1 - top2;
    o[p.d + 2] = ent / log(kk);
    o[p.d + 3] = kk / 255.0f;
}

// ---------------------------------------------------------------------------
// Attention over packed sequences, head_dim 64.
//
// One threadgroup (4 simdgroups) per (block of 32 queries of one sequence,
// head); each simdgroup owns 8 query rows. Keys and values stream through
// threadgroup memory 32 at a time with an online softmax (flash attention),
// using simdgroup 8×8 matrices for Q·Kᵀ and P·V. window < 0 is full
// bidirectional attention within the sequence; otherwise query i sees key j
// only when |i − j| ≤ window.
// ---------------------------------------------------------------------------

struct AttnParams {
    uint d;      // hidden width (row stride of out; qkv rows are 3d)
    int window;  // < 0: global
    float scale; // 1/sqrt(64)
};

constant constexpr uint HD = 64;
constant constexpr uint SK = HD + 4; // padded row stride for K and V tiles

// One threadgroup (4 simdgroups) per (block of 32 queries of one sequence,
// head). Each simdgroup owns 8 query rows and walks only the keys its rows
// can see, 32 at a time, with an online softmax (flash attention); Q, K and
// V fragments are loaded straight from device memory and Q·Kᵀ and P·V use
// simdgroup 8×8 matrices. The threadgroup holds just the score and
// correction staging. qkv must have readable rows up to 32 past the last
// token (the host pads it); those rows are masked out of the softmax.
kernel void attention(device const float* qkv [[buffer(0)]],
                       device float* out [[buffer(1)]],
                       device const uint4* blocks [[buffer(2)]],
                       constant AttnParams& p [[buffer(3)]],
                       uint2 tg [[threadgroup_position_in_grid]],
                       uint sg [[simdgroup_index_in_threadgroup]],
                       uint lane [[thread_index_in_simdgroup]]) {
    threadgroup float Ss[4 * 8 * 32];
    threadgroup float Ds[4 * 64];
    uint4 bl = blocks[tg.x];
    uint h = tg.y;
    uint s0 = bl.x, L = bl.y;
    uint r0 = bl.z + sg * 8; // first query row of this simdgroup, within the sequence
    if (r0 >= L) return;
    uint ld = 3 * p.d;
    int W = p.window;
    threadgroup float* S = Ss + sg * 256;
    threadgroup float* D = Ds + sg * 64;
    D[lane] = 0;
    D[lane + 32] = 0;

    simdgroup_float8x8 Q[8];
    device const float* qp = qkv + (ulong)(s0 + r0) * ld + h * HD;
    for (uint kk = 0; kk < 8; kk++) simdgroup_load(Q[kk], qp + kk * 8, ld);

    uint kbeg = 0, kend = L;
    if (W >= 0) {
        kbeg = uint(max(0, int(r0) - W));
        kend = min(L, r0 + 8 + uint(W));
    }
    simdgroup_float8x8 O[8];
    for (uint f = 0; f < 8; f++) O[f] = make_filled_simdgroup_matrix<float, 8, 8>(0.0f);
    float m[8], l[8];
    for (uint r = 0; r < 8; r++) { m[r] = -INFINITY; l[r] = 0; }

    for (uint kc = kbeg; kc < kend; kc += 32) {
        device const float* kp = qkv + (ulong)(s0 + kc) * ld + p.d + h * HD;
        for (uint c = 0; c < 4; c++) {
            simdgroup_float8x8 acc = make_filled_simdgroup_matrix<float, 8, 8>(0.0f);
            for (uint kk = 0; kk < 8; kk++) {
                simdgroup_float8x8 b;
                simdgroup_load(b, kp + (ulong)c * 8 * ld + kk * 8, ld, ulong2(0, 0), true);
                simdgroup_multiply_accumulate(acc, Q[kk], b, acc);
            }
            simdgroup_store(acc, S + c * 8, 32);
        }
        simdgroup_barrier(mem_flags::mem_threadgroup);

        uint j = kc + lane;
        for (uint r = 0; r < 8; r++) {
            int i = int(r0 + r);
            bool ok = j < kend && (W < 0 || abs(i - int(j)) <= W);
            float sc = ok ? S[r * 32 + lane] * p.scale : -INFINITY;
            float mn = max(m[r], simd_max(sc));
            float pr = ok ? exp(sc - mn) : 0.0f;
            float corr = (m[r] == -INFINITY) ? 0.0f : exp(m[r] - mn);
            l[r] = l[r] * corr + simd_sum(pr);
            m[r] = mn;
            S[r * 32 + lane] = pr;
            if (lane == 0) D[r * 9] = corr;
        }
        simdgroup_barrier(mem_flags::mem_threadgroup);

        simdgroup_float8x8 dm;
        simdgroup_load(dm, D, 8);
        for (uint f = 0; f < 8; f++) simdgroup_multiply(O[f], dm, O[f]);
        device const float* vp = qkv + (ulong)(s0 + kc) * ld + 2 * p.d + h * HD;
        for (uint c = 0; c < 4; c++) {
            simdgroup_float8x8 pm;
            simdgroup_load(pm, S + c * 8, 32);
            for (uint f = 0; f < 8; f++) {
                simdgroup_float8x8 vm;
                simdgroup_load(vm, vp + (ulong)c * 8 * ld + f * 8, ld);
                simdgroup_multiply_accumulate(O[f], pm, vm, O[f]);
            }
        }
        simdgroup_barrier(mem_flags::mem_threadgroup);
    }

    // 1/l per row through threadgroup memory, then each thread writes its
    // two elements of every output fragment.
    if (lane < 8) {
        float lv = 0;
        for (uint r = 0; r < 8; r++) lv = (r == lane) ? l[r] : lv;
        S[lane] = 1.0f / lv;
    }
    simdgroup_barrier(mem_flags::mem_threadgroup);
    uint q = lane / 4;
    uint fm = (q & 4) + ((lane / 2) % 4);
    uint fn = (q & 2) * 2 + (lane % 2) * 2;
    if (r0 + fm >= L) return;
    float inv = S[fm];
    device float* o = out + (ulong)(s0 + r0 + fm) * p.d + h * HD + fn;
    for (uint f = 0; f < 8; f++) {
        thread auto& v = O[f].thread_elements();
        *(device float2*)(o + f * 8) = float2(v[0], v[1]) * inv;
    }
}

// gather: out[r] = in[idx[r]] for rows of d floats. One threadgroup per row.
kernel void gather(device const float4* in [[buffer(0)]],
                   device float4* out [[buffer(1)]],
                   device const int* idx [[buffer(2)]],
                   constant uint& d4 [[buffer(3)]],
                   uint row [[threadgroup_position_in_grid]],
                   uint tid [[thread_index_in_threadgroup]]) {
    ulong src = (ulong)idx[row] * d4, dst = (ulong)row * d4;
    for (uint j = tid; j < d4; j += 256) out[dst + j] = in[src + j];
}
